/** `<Out>` is `<notatio-out>`: props are the element's attributes, typed. */
export interface OutProps extends Common {
  /** The expression to render, in the encoding `format` names. */
  value?: string;
  /** How to read `value`: `latex`, `mathjson` or `epsil`. */
  format?: string;
  /** Sit inline in a sentence: the rendering alone, no label, no menu, no status. */
  inline?: boolean;
  /** Set as a centred display equation (`\displaystyle`), for `$$…$$`. */
  display?: boolean;
  /** Evaluate before rendering, rather than rendering the input as given. */
  evaluate?: boolean;
  /** Box without evaluating, so the source and AST forms populate. */
  box?: boolean;
  /** Box without canonicalising, so the expression shows as authored -- `a - b` stays a `Subtract`, `a > b` is not flipped into a `Less`. For a definition, whose spelling is the point. Ignored when `evaluate` is set. */
  raw?: boolean;
  /** A MathJSON value to assert the result against; a mismatch is reported inline. */
  expect?: string;
  /** Mark an `expect` mismatch as a known gap — shown as a note rather than a failure. */
  planned?: boolean;
  /** The representation to show, e.g. `standard`, `traditional`, `fullform`, `numpy`. */
  form?: string;
  /** Row label, e.g. `In` or `Out`. */
  label?: string;
  /** A preset to reduce the picture for (`print`, `pipe`, …); by default the page's own, as it changes. */
  env?: string;
  /** Above this many operands, describe a `List` result rather than typeset it (`0`, the default, never elides). A long numeric result costs real time to serialize and typeset for an output line that exists to be *drawn*, not read -- see `elideResult`. General: any cell over a control that can grow a long result can set this, not only a worksheet's. */
  elideAbove?: number;
  /** Also report the substituted-but-unevaluated form of the input, in the `notatio-result` event's `plot` detail, for a consumer that draws the INPUT rather than the fully-evaluated output -- so a complex portrait or plot doesn't collapse at a pole a bound parameter crosses (`substitutedForm`). Only meaningful for a cell inside a `<notatio-dynamic-module>` (`evaluate` and a shared scope); ignored otherwise. */
  plot?: boolean;
  /** Read-only: set while the value is being evaluated or typeset (the engine loads lazily, so the first one can take a moment). Styled as a pending state; a script can wait for `:not([busy])`. */
  busy?: boolean;
  /** Put the form menu on the label instead of a selector at the right: click `In`/`Out` to open it. Leaves the right of the row free. */
  labelMenu?: boolean;
}
export function Out(props: OutProps): ReactElement {
  const { children, ...rest } = props;
  return createElement("notatio-out", bound(rest, {}), children);
}

